class TestCoordinationRules:
    """Tests for coordination with active work and prior solutions."""

    def test_reconcile_with_active_loop_work(self):
        active_work = {"branch": "agent/madeus-brand-recovery-20260722", "status": "in-progress"}
        new_task = {"branch": "agent/rework-buildfail-qafix-tomorrow", "source": "native-claim"}
        # Different branches should not conflict
        assert active_work["branch"] != new_task["branch"]

    def test_reuse_prior_solutions_before_drafting(self):
        prior_solutions = [
            {"id": "pareto-2080/qafix-pareto-2080-07062319-slice-1-slice-1-slice-4", "similarity": 0.434},
            {"id": "pareto-2080/qafix-pareto-2080-07062319-slice-1-slice-4", "similarity": 0.515},
        ]
        # Should select highest similarity first
        best_match = max(prior_solutions, key=lambda x: x["similarity"])
        assert best_match["similarity"] == 0.515

    def test_do_not_delete_unrelated_queued_work(self):
        queued_work = [
            {"id": "task-1", "project": "tomorrow"},
            {"id": "task-2", "project": "pareto-2080"},
        ]
        new_task_project = "tomorrow"
        # Queued work from different projects should be preserved
        preserved = [t for t in queued_work if t["project"] != new_task_project]
        assert len(preserved) == 1
        assert preserved[0]["project"] == "pareto-2080"

    def test_recovered_work_remains_in_queue(self):
        recovered_work = {"id": "recovered-task", "status": "recovered", "priority": "ship"}
        assert recovered_work["status"] == "recovered"
        # Should not auto-execute, but queue for shipping
        assert recovered_work["priority"] in ["ship", "queue"]


